export class VersionedSchemaRegistry{constructor(){this.rows=new Map()} register({providerId,operationId,version,schemaHash,schema,approved=false}){if(!providerId||!operationId||!version||!schemaHash)throw new Error('SCHEMA_REGISTRY_FIELDS_REQUIRED');const k=`${providerId}::${operationId}::${version}`;if(this.rows.has(k)&&this.rows.get(k).schemaHash!==schemaHash)throw new Error('SCHEMA_VERSION_HASH_CONFLICT');this.rows.set(k,{providerId,operationId,version,schemaHash,schema,approved:!!approved});return this.rows.get(k)} latest(providerId,operationId,{approvedOnly=true}={}){return [...this.rows.values()].filter(x=>x.providerId===providerId&&x.operationId===operationId&&(!approvedOnly||x.approved)).sort((a,b)=>String(b.version).localeCompare(String(a.version),undefined,{numeric:true}))[0]||null}}
export function schemaPublishDecision({registered,observedHash,breaking=false}={}){if(!registered)return {allow:false,reason:'NO_REGISTERED_SCHEMA'};if(breaking)return {allow:false,reason:'BREAKING_DRIFT'};if(registered.schemaHash===observedHash)return {allow:true,reason:'REGISTERED_MATCH'};return {allow:false,reason:'UNAPPROVED_SCHEMA_HASH'}}
